WITH enriched AS (SELECT *, SUM(sqft) OVER (PARTITION BY city, region ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft, AVG(sqft) OVER (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS sqft_avg_3_prior, AVG(sqft) OVER (PARTITION BY city ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS sqft_avg_6_prior FROM stores) SELECT id, store_name, city, region, sqft, sqft_avg_3_prior, sqft_avg_6_prior FROM enriched ORDER BY id DESC LIMIT 5;
